const express = require('express');
const { SNSClient, SubscribeCommand } = require('@aws-sdk/client-sns');
const { OrganizationTenant } = require('../models/organization');

const app = express();
app.use(express.json());

const sns = new SNSClient({ region: 'us-east-1' });

app.post('/api/monitoring/sns/subscribe-audit', async (req, res) => {
  if (!req.user || !req.user.tenantId || !req.user.isAdmin) {
    return res.status(403).json({ error: 'Tenant administrative privilege required' });
  }

  const { tenantTopicArn, webhookEndpointUrl } = req.body;

  if (!tenantTopicArn || !webhookEndpointUrl) {
    return res.status(400).json({ error: 'tenantTopicArn and webhookEndpointUrl are required' });
  }

  // Validate that the requested topic ARN belongs to the caller's authorized tenant
  const tenant = await OrganizationTenant.findById(req.user.tenantId);
  if (!tenant || tenant.snsAuditTopicArn !== tenantTopicArn) {
    return res.status(403).json({ error: 'Access denied: topic does not belong to authorized tenant' });
  }

  const subscribeCmd = new SubscribeCommand({
    TopicArn: tenant.snsAuditTopicArn,
    Protocol: 'https',
    Endpoint: webhookEndpointUrl,
    ReturnSubscriptionArn: true
  });

  try {
    const result = await sns.send(subscribeCmd);
    res.json({
      success: true,
      subscriptionArn: result.SubscriptionArn
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to register SNS subscriber' });
  }
});

app.listen(3006);
